return $input.all().map((item) => {
  const input = item.json;
  const event = input.event;
  if (!input.isSchedule) return { json: { ...input, calendarAction: 'skip', calendarReason: 'not_schedule' } };
  if (!event || typeof event.title !== 'string' || !event.title.trim()) return { json: { ...input, calendarAction: 'skip', calendarReason: 'missing_title' } };
  const startMs = Date.parse(event.startDateTime);
  if (Number.isNaN(startMs)) return { json: { ...input, calendarAction: 'skip', calendarReason: 'missing_start_datetime' } };
  if (typeof input.mailLogId !== 'string' || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(input.mailLogId)) throw new Error('mailLogId must be a UUID');
  let endMs = event.endDateTime ? Date.parse(event.endDateTime) : startMs + 60 * 60 * 1000;
  if (Number.isNaN(endMs) || endMs <= startMs) throw new Error('event endDateTime must be after startDateTime');
  return { json: { ...input, calendarAction: 'register', calendarEventId: `m${input.mailLogId.replaceAll('-', '').toLowerCase()}`, calendarTitle: event.title.trim(), calendarStart: new Date(startMs).toISOString(), calendarEnd: new Date(endMs).toISOString(), calendarLocation: typeof event.location === 'string' ? event.location : '' } };
});

const status = Number($json.statusCode ?? $json.httpCode ?? $json.error?.statusCode);
const prepared = $('Prepare Calendar Event').item.json;
if (status === 409) return [{ json: { ...prepared, googleEventId: prepared.calendarEventId, calendarRecovered: true } }];
throw new Error(`Google Calendar registration failed (status: ${Number.isFinite(status) ? status : 'unknown'})`);

