INSERT INTO calendar_logs (mail_log_id, google_event_id, title, start_datetime, end_datetime, location, status)
SELECT $1, $2, $3, $4, $5, $6, 'created'
WHERE NOT EXISTS (
  SELECT 1 FROM calendar_logs WHERE mail_log_id = $1 AND status = 'created'
)
RETURNING id, mail_log_id, google_event_id, status;
